import type { Question } from "@/lib/server/questions";

type Difficulty = "beginner" | "intermediate" | "advanced";
const answerPositions = [2, 0, 3, 1, 1, 3, 0, 2, 2, 1, 3, 0, 1, 2, 0];
const testSkillOrder = ["fullstack", "python", "java", "devops"];

function mcq(
  id: string,
  skillId: string,
  stage: number,
  difficulty: Difficulty,
  text: string,
  options: [string, string, string, string],
  answer: number,
  explanation: string
): Question {
  const questionNumber = Number(id.slice(id.lastIndexOf("q") + 1));
  const skillOffset = testSkillOrder.indexOf(skillId);
  const correctPosition =
    (answerPositions[(questionNumber - 1) % answerPositions.length] + skillOffset) % options.length;
  const randomizedOptions = [...options];
  [randomizedOptions[answer], randomizedOptions[correctPosition]] =
    [randomizedOptions[correctPosition], randomizedOptions[answer]];
  return {
    id,
    skillId,
    type: "mcq",
    stage,
    difficulty,
    text,
    options: randomizedOptions,
    answer: correctPosition,
    explanation,
  };
}

